"""Las 12 páginas (ES/EN) de los seis simuladores de IC1 de la v1.3, con la estructura de las del codificador (5061/5062):
entradilla, [sl_sim], «Cómo se usa», qué calcula, «Los criterios que sigue» y «Para el examen». Escribe <dir>/<clave>-<es|en>.html,
los fragmentos y posts.json (con sha). Uso: python3 paginas-ic1b.py <dir> <snip22> <snip35> <snip18>"""
import json, hashlib, os, re, sys
D = sys.argv[1]; os.makedirs(D, exist_ok=True)
def anchor(t):
    import unicodedata
    t = unicodedata.normalize('NFD', t.lower()); t = ''.join(c for c in t if unicodedata.category(c) != 'Mn')
    return re.sub(r'[^a-z0-9]+', '-', t).strip('-')
def H2(t): a = anchor(t); return f'<!-- wp:heading {{"anchor":"{a}"}} -->\n<h2 class="wp-block-heading" id="{a}">{t}</h2>\n<!-- /wp:heading -->\n\n'
def P(t): return f'<!-- wp:paragraph -->\n<p>{t}</p>\n<!-- /wp:paragraph -->\n\n'
def L(items, ordered=False):
    tag = 'ol' if ordered else 'ul'
    head = '<!-- wp:list {"ordered":true} -->' if ordered else '<!-- wp:list -->'
    return head + f'\n<{tag} class="wp-block-list">' + ''.join(f'<!-- wp:list-item -->\n<li>{x}</li>\n<!-- /wp:list-item -->\n' for x in items) + f'</{tag}>\n<!-- /wp:list -->\n\n'
def page(lead, sc, use, howT, how, crit, exam, L_):
    T = {'es': ('Cómo se usa', 'Los criterios que sigue', 'Para el examen'), 'en': ('How to use it', 'The rules it follows', 'For the exam')}[L_]
    s = f'<!-- wp:html -->\n<p class="sl6-lead">{lead}</p>\n<!-- /wp:html -->\n\n<!-- wp:shortcode -->\n[sl_sim id="{sc}"]\n<!-- /wp:shortcode -->\n\n'
    s += H2(T[0]) + L(use, True) + H2(howT) + ''.join(P(x) for x in how) + H2(T[1]) + L(crit) + H2(T[2]) + P(exam)
    return s.rstrip() + '\n'
