posts = {}
for k, p in PAGES.items():
    for i, L_ in enumerate(('es', 'en')):
        c = p[L_]; html = page(c['lead'], k, c['use'], c['howT'], c['how'], c['crit'], c['exam'], L_)
        f = f'{k}-{L_}.html'; open(f'{D}/{f}', 'w').write(html)
        posts[f'{k}-{L_}'] = {'file': f, 'sha': hashlib.sha256(html.encode()).hexdigest()[:16], 'slug': p['slug'][i], 'title': p['title'][i], 'order': p['order'], 'seo': list(p['seo'][i]), 'lang': L_}
for key, src, name in (('snip22', sys.argv[2], 'snip22-v13.txt'), ('snip35', sys.argv[3], 'snip35-v21.txt'), ('snip18', sys.argv[4], 'snip18-v21.txt')):
    s = open(src).read(); s = s[5:].lstrip('\n') if s.startswith('<?php') else s
    open(f'{D}/{name}', 'w').write(s); posts[key] = {'file': name, 'sha': hashlib.sha256(s.encode()).hexdigest()[:16]}
json.dump(posts, open(f'{D}/posts.json', 'w'), ensure_ascii=False, indent=1)
